/* Admin-only panel. Server endpoints enforce fresh admin role and recent 2FA. */
async function renderBackupPolicy(container){
 if(!container||!superadmin())return;
 container.innerHTML='<p class="muted" aria-live="polite">Caricamento della copia separata…</p>';
 const time=value=>value?new Date(value).toLocaleString('it-IT',{dateStyle:'medium',timeStyle:'short'}):'Mai eseguita';
 try{
  const data=await api('backup_policy');if(!container.isConnected)return;
  const probe=data.last_probe;
  container.innerHTML=`<section class="panel backup-policy-panel" aria-labelledby="backupPolicyTitle"><span class="eyebrow">CONTINUITÀ DEI DATI</span><h2 id="backupPolicyTitle">Copia su destinazione separata</h2><p class="muted">Una seconda copia completa del database, inclusi i documenti HR caricati da qualsiasi sede. ${esc(data.schedule)}</p><div class="backup-policy-stats"><div><strong>${data.enabled?'Attiva':'Disattivata'}</strong><span>Copia automatica</span></div><div><strong>${esc(time(data.last_success))}</strong><span>Ultima copia verificata</span></div><div><strong>${probe?esc(time(probe.at)):'Mai eseguita'}</strong><span>Prova di ripristino${probe?(probe.ok?' superata':' non riuscita'):''}</span></div></div>${data.last_error?`<div class="error" role="alert"><b>Ultimo tentativo non riuscito.</b> ${esc(data.last_error)} Le copie precedenti restano disponibili.</div>`:''}${data.retention_error?`<div class="error" role="alert"><b>Conservazione sospesa.</b> ${esc(data.retention_error)}</div>`:''}${data.destination_error?`<div class="error" role="alert">${esc(data.destination_error)}</div>`:''}<form id="backupPolicyForm"><div class="backup-policy-fields"><label class="backup-policy-toggle"><input type="checkbox" id="backupPolicyEnabled" ${data.enabled?'checked':''}>Attiva la copia automatica separata</label><label class="backup-policy-wide">Cartella di destinazione sul server<input id="backupPolicyDestination" type="text" value="${esc(data.destination)}" maxlength="2048" placeholder="/mnt/backup-aziendale/presenze" autocomplete="off"><small>Cartella esistente, predisposta dal tecnico su un volume o una condivisione aziendale. Non può essere la cartella dati o contenere collegamenti simbolici.</small></label><label>Numero di copie da conservare<input id="backupPolicyRetention" type="number" min="0" max="10000" step="1" value="${data.retention_count}" required><small>0 = conserva tutto. Con un limite, elimina solo vecchie copie gestite dopo una nuova copia verificata. I backup locali originali restano.</small></label><label>Prova automatica ogni quanti giorni<input id="backupPolicyProbeDays" type="number" min="1" max="365" step="1" value="${data.probe_interval_days}" required><small>La prima copia include sempre una prova. Verifica anche le impronte di tutti gli allegati HR su una copia temporanea, poi la rimuove.</small></label></div><p class="backup-policy-note">${esc(data.protection_note)}${data.same_filesystem===true?' <b>La destinazione risulta sullo stesso filesystem dei dati: verificarne l’indipendenza con il tecnico.</b>':''}</p><div class="backup-policy-actions"><button class="btn primary" type="submit">Salva configurazione</button><button class="btn" id="backupPolicyRun" type="button" ${data.enabled?'':'disabled'}>Copia adesso</button><button class="btn" id="backupPolicyProbe" type="button" ${data.enabled?'':'disabled'}>Copia e prova ripristino</button></div><div id="backupPolicyMessage" aria-live="polite"></div></form>${probe?`<details class="backup-policy-details"><summary>Dettaglio ultima prova</summary><p>${esc(probe.detail)}</p>${probe.ok?`<p>${Number(probe.rows?.hr_documents||0).toLocaleString('it-IT')} allegati HR verificati; ${Number(probe.rows?.people||0).toLocaleString('it-IT')} anagrafiche; ${Number(probe.rows?.entries||0).toLocaleString('it-IT')} registrazioni presenze.</p>`:''}</details>`:''}</section>`;
  const form=container.querySelector('#backupPolicyForm');
  const operation=async(action,body,success)=>{
   const buttons=form.querySelectorAll('button');buttons.forEach(button=>button.disabled=true);
   const message=container.querySelector('#backupPolicyMessage');message.textContent='Operazione in corso…';
   try{await api(action,body);toast(success);if(container.isConnected)await renderBackupPolicy(container)}
   catch(error){if(message.isConnected){message.className='error';message.textContent=error.message}}
   finally{if(form.isConnected){buttons.forEach(button=>button.disabled=false);if(!data.enabled){container.querySelector('#backupPolicyRun').disabled=true;container.querySelector('#backupPolicyProbe').disabled=true}}}
  };
  form.onsubmit=event=>{event.preventDefault();operation('backup_policy_save',{enabled:container.querySelector('#backupPolicyEnabled').checked,destination:container.querySelector('#backupPolicyDestination').value.trim(),retention_count:Number(container.querySelector('#backupPolicyRetention').value),probe_interval_days:Number(container.querySelector('#backupPolicyProbeDays').value)},'Configurazione backup salvata. La copia automatica seguirà il controllo periodico.')};
  container.querySelector('#backupPolicyRun').onclick=()=>operation('backup_policy_run',{probe:false},'Copia separata verificata.');
  container.querySelector('#backupPolicyProbe').onclick=()=>operation('backup_policy_run',{probe:true},'Copia e prova di ripristino completate.');
 }catch(error){if(container.isConnected)container.innerHTML='<div class="error" role="alert">'+esc(error.message)+'</div>'}
}
